CREATE TABLE IF NOT EXISTS studios(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), studio_id uuid NOT NULL REFERENCES studios, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','staff','client')), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(id_hash text PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), studio_id uuid NOT NULL REFERENCES studios, client_id uuid NOT NULL REFERENCES accounts, title text NOT NULL, description text NOT NULL DEFAULT '', stage text NOT NULL DEFAULT 'brief', created_at timestamptz DEFAULT now(), CHECK(stage IN ('brief','concept','quote','approved','fabrication','installation','delivery','closed','cancelled')));
CREATE TABLE IF NOT EXISTS quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, version int NOT NULL CHECK(version>0), lines jsonb NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>=0), currency text NOT NULL DEFAULT 'eur', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','revision','withdrawn')), created_at timestamptz DEFAULT now(), UNIQUE(project_id,version));
CREATE UNIQUE INDEX IF NOT EXISTS quote_pending ON quotes(project_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_id uuid NOT NULL UNIQUE REFERENCES quotes, account_id uuid NOT NULL REFERENCES accounts, digest text NOT NULL, consent text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, storage_key text NOT NULL UNIQUE, name text NOT NULL, mime text NOT NULL, size_bytes bigint NOT NULL, visible boolean NOT NULL DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects, quote_id uuid NOT NULL UNIQUE REFERENCES quotes, amount_cents bigint NOT NULL CHECK(amount_cents>0), provider_id text UNIQUE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid')), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS stripe_events(id text PRIMARY KEY, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent')), attempts int NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, studio_id uuid NOT NULL REFERENCES studios, account_id uuid REFERENCES accounts, action text NOT NULL, entity_id uuid, created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_studio ON projects(studio_id,client_id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
